      imports: [MovieList],
      providers: [provideHttpClient(), provideHttpClientTesting(), provideRouter([]), provideNativeDateAdapter()],
    });
    http = TestBed.inject(HttpTestingController);
    fixture = TestBed.createComponent(MovieList);
  });

  afterEach(() => http.verify());

  function element(testId: string): HTMLElement | null {
    return fixture.nativeElement.querySelector(`[data-testid="${testId}"]`);
  }

  function all(testId: string): HTMLElement[] {
    return Array.from(fixture.nativeElement.querySelectorAll(`[data-testid="${testId}"]`));
  }

  function flushToday(movieList: Movie[], screeningList: Screening[]): void {
    http.expectOne(`${API}/movies`).flush(movieList);
    http.expectOne((req) => req.url === `${API}/screenings` && req.params.get('date') === today).flush(screeningList);
    fixture.detectChanges();
  }

  it('shows the loading indicator and no cards while requests are in flight', () => {
    fixture.detectChanges();
    expect(element('movies-loading')?.textContent).toContain('Loading');
    expect(all('movie-card')).toHaveLength(0);
    flushToday(movies, screenings);
    expect(element('movies-loading')).toBeNull();
  });

  it('renders one card per movie with a screening today, with sorted screening buttons', () => {
    fixture.detectChanges();
    flushToday(movies, screenings);

    const cards = all('movie-card');
    expect(cards.map((card) => card.getAttribute('data-movie-id'))).toEqual(['1', '2']);
    expect(cards[0].querySelector('[data-testid="movie-title"]')?.textContent).toContain('The Silent Harbor');
    expect(cards[0].querySelector('[data-testid="movie-runtime"]')?.textContent).toContain('128 min');
    expect(cards[0].querySelector('[data-testid="movie-format"]')?.textContent).toContain('PL subtitles');
    const times = Array.from(cards[0].querySelectorAll('[data-testid="screening-button"]')).map((b) => b.textContent?.trim());
    expect(times).toEqual(['16:00', '19:30']);
    expect(cards[0].querySelector('[data-testid="screening-button"]')?.getAttribute('data-screening-id')).toBe('1');
  });

  it('shows the empty text when no movie has a screening on the day', () => {
    fixture.detectChanges();
    flushToday(movies, []);
    expect(element('movies-empty')?.textContent).toContain('No screenings on this day');
    expect(all('movie-card')).toHaveLength(0);
  });

  it('shows an error with Retry that reissues the requests', () => {
    fixture.detectChanges();
    http.expectOne(`${API}/movies`).flush('boom', { status: 500, statusText: 'Server Error' });
    http.expectOne((req) => req.url === `${API}/screenings`).flush('boom', { status: 500, statusText: 'Server Error' });
    fixture.detectChanges();
    expect(element('movies-error')?.textContent).toContain('Failed to load movies');

    element('movies-retry-button')?.click();
    fixture.detectChanges();
    expect(element('movies-loading')).not.toBeNull();
    flushToday(movies, screenings);
    expect(all('movie-card')).toHaveLength(2);
  });

  it('marks Today as the selected day by default', () => {
    fixture.detectChanges();
    flushToday(movies, screenings);
    const days = all('day-button');
    expect(days).toHaveLength(5);
    expect(days[0].getAttribute('data-date')).toBe(today);
    expect(days[0].getAttribute('data-selected')).toBe('true');
    expect(days[0].textContent?.trim()).toBe('Today');
  });
});

