input.content:
:host {
  display: block;
  --seat: 32px;
  --aisle: 64px;
  --cell-gap: 4px;
}

.seat-page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
}

h1 {
  margin: 0;
  font-size: 28px;
  font-weight: 500;
}

.subtitle,
.limit {
  margin: 0;
}

.limit {
  color: var(--mat-sys-on-surface-variant);
}

.auditorium {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-top: 8px;
}

.screen {
  width: 100%;
  padding: 6px 0;
  border-radius: 4px;
  background-color: var(--mat-sys-surface-container-highest);
  font-size: 12px;
  letter-spacing: 6px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: var(--cell-gap);
}

.seat-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.row-label {
  width: 24px;
  text-align: right;
  font-size: 12px;
  color: var(--mat-sys-on-surface-variant);
}

.cells {
  display: grid;
  grid-template-columns:
    repeat(4, var(--seat))
    var(--aisle)
    repeat(16, var(--seat))
