@if (view(); as view) {
  <main class="seat-page">
    <h1 data-testid="seat-map-title">Choose your seats</h1>
    <p class="subtitle" data-testid="seat-map-subtitle">{{ view.subtitle }}</p>
    <p class="limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>

    <div class="auditorium">
      <div class="screen" data-testid="screen-indicator">SCREEN</div>
      <div class="seat-map" data-testid="seat-map">
        @for (row of rows; track row.row) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.row">
            <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.row">{{ row.row }}</span>
            <div class="cells">
              @for (cell of row.cells; track $index) {
                @if (cell.kind === 'entrance') {
                  <div class="entrance"></div>
                } @else if (cell.kind === 'aisle') {
                  <div class="aisle" data-testid="aisle" [attr.data-row]="row.row"></div>
                } @else if (cell.kind === 'seat') {
                  <div
                    class="seat"
                    data-testid="seat"
                    [attr.data-row]="cell.row"
                    [attr.data-column]="cell.column"
                    [attr.data-state]="seatState(cell)"
                    (click)="clickSeat(cell)"
                  >
                    {{ cell.column }}
                  </div>
                } @else {
                  <div
                    class="couch"
                    data-testid="couch"
                    [attr.data-row]="cell.row"
                    [attr.data-column-start]="cell.columnStart"
                    [attr.data-column-end]="cell.columnEnd"
                    [attr.data-state]="couchState(cell)"
                    (click)="clickCouch(cell)"
                  >
                    {{ cell.columnStart }}-{{ cell.columnEnd }}
                  </div>
                }
              }
            </div>
            <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.row">{{ row.row }}</span>
          </div>
        }
      </div>
    </div>

    <div class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <div class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
          <span class="swatch"></span>{{ item.label }}
        </div>
      }
    </div>

    <section class="selected-seats" data-testid="selected-seats">
      <p data-testid="selected-seats-count">Selected seats: {{ seatCount() }}</p>
      @for (line of selectedRows(); track line.row) {
        <p data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.labels }}</p>
      }
    </section>

    <div class="actions">
      <button mat-stroked-button type="button" data-testid="cancel-button" (click)="cancel()">Cancel</button>
      <button
        mat-flat-button
        type="button"
        data-testid="continue-button"
        [disabled]="seatCount() === 0"
        (click)="continueToSummary()"
      >
        Continue
      </button>
    </div>
  </main>
}

