:host {
  display: block;
  --seat: 32px;
  --aisle: 64px;
  --cell-gap: 4px;
}

.seat-page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
}

h1 {
  margin: 0;
  font-size: 28px;
  font-weight: 500;
}

.subtitle,
.limit {
  margin: 0;
}

.limit {
  color: var(--mat-sys-on-surface-variant);
}

.auditorium {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-top: 8px;
}

.screen {
  width: 100%;
  padding: 6px 0;
  border-radius: 4px;
  background-color: var(--mat-sys-surface-container-highest);
  font-size: 12px;
  letter-spacing: 6px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: var(--cell-gap);
}

.seat-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.row-label {
  width: 24px;
  text-align: right;
  font-size: 12px;
  color: var(--mat-sys-on-surface-variant);
}

.cells {
  display: grid;
  grid-template-columns:
    repeat(4, var(--seat))
    var(--aisle)
    repeat(16, var(--seat))
    var(--aisle)
    repeat(4, var(--seat));
  gap: var(--cell-gap);
}

.entrance {
  grid-column: span 4;
}

.aisle {
  grid-column: span 1;
}

.seat,
.couch {
  height: var(--seat);
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  border-radius: 6px;
  color: #fff;
  font-size: 12px;
  user-select: none;
  cursor: pointer;

  &[data-state='unavailable'] {
    background-color: #c62828;
    cursor: not-allowed;
  }

  &[data-state='available'] {
    background-color: #2e7d32;
  }

  &[data-state='accessible'] {
    background-color: #1565c0;
  }

  &[data-state='selected'] {
    background-color: #f9a825;
    color: #212121;
  }
}

.seat {
  width: var(--seat);
}

.couch {
  grid-column: span 2;
}

.legend {
  display: flex;
  gap: 24px;
  margin-top: 8px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;

  .swatch {
    width: 16px;
    height: 16px;
    border-radius: 4px;
  }

  &[data-state='available'] .swatch {
    background-color: #2e7d32;
  }

  &[data-state='selected'] .swatch {
    background-color: #f9a825;
  }

  &[data-state='unavailable'] .swatch {
    background-color: #c62828;
  }

  &[data-state='accessible'] .swatch {
    background-color: #1565c0;
  }
}

.selected-seats {
  p {
    margin: 2px 0;
  }
}

.actions {
  display: flex;
  gap: 12px;
  margin-top: 8px;
}
